export const getCitiesByCountry = (countryName: string): WorldCityOption[] => {
  if (!countryName) return WORLD_CITIES_DIRECTORY;
  const normalized = countryName.trim().toLowerCase();
  return WORLD_CITIES_DIRECTORY.filter(c => c.country.toLowerCase() === normalized);
};
